mapper.select:
SELECT * FROM memory_import_source
WHERE tenant_id = #{tenantId} AND agent_id = #{agentId}
  AND provider_family = #{providerFamily} AND logical_path = #{logicalPath}
  AND installation_fingerprint = #{installationFingerprint} LIMIT 1

mapper.delete:
DELETE FROM memory_import_snapshot
WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
  AND id IN (
    SELECT id FROM (
      SELECT id FROM memory_import_snapshot
      WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
      ORDER BY id DESC LIMIT 18446744073709551615 OFFSET 2
    ) old_snapshots
  )

mapper.select:
SELECT * FROM memory_import_snapshot
WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
ORDER BY id DESC LIMIT 2

SELECT * FROM memory_import_snapshot
WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
  AND sanitized_content_sha256 = #{sanitizedContentSha256}
LIMIT 1

mapper.update:
UPDATE memory_import_snapshot
SET status = 'RUNNING', curation_lease_id = #{leaseId}, curation_lease_until = #{leaseUntil}
WHERE tenant_id = #{tenantId} AND id = #{snapshotId}
  AND (status IN ('QUEUED', 'FAILED')
       OR (status = 'RUNNING' AND curation_lease_until < #{now}))

UPDATE memory_import_snapshot SET curation_lease_until = #{leaseUntil}
WHERE tenant_id = #{tenantId} AND id = #{snapshotId} AND status = 'RUNNING'
  AND curation_lease_id = #{leaseId} AND curation_lease_until > #{now}

mapper.select:
SELECT * FROM memory_import_source
WHERE tenant_id = #{tenantId}
ORDER BY id DESC

SELECT * FROM memory_import_receipt
WHERE tenant_id = #{tenantId} AND source_id = #{sourceId}
ORDER BY id DESC LIMIT #{limit}

mapper.update:
UPDATE memory_import_source
SET status = #{status}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{sourceId} AND version = #{version}

UPDATE memory_import_source
SET status = 'STALE', version = version + 1
WHERE status IN ('OBSERVED', 'ACTIVE') AND last_seen_at < #{cutoff}
